/** [H15] How long a livery change cross-fades when the spec resolves its theme from the values. */
const val LIVERY_MS = 350.0

/** [H15] _ThemeTween: the six colours the livery cross-fades; ratios and alert come from [b]. */
fun lerpTheme(a: PlateTheme, b: PlateTheme, t: Double) = b.copy(
    plateBackground = lerpColor(a.plateBackground, b.plateBackground, t),
    plateBorder = lerpColor(a.plateBorder, b.plateBorder, t),
    ink = lerpColor(a.ink, b.ink, t),
    dividerColor = lerpColor(a.dividerColor, b.dividerColor, t),
    activeColor = lerpColor(a.activeColor, b.activeColor, t),
    inactiveColor = lerpColor(a.inactiveColor, b.inactiveColor, t),
)

/** [H4] The theme a plate paints with: the spec's overrides on [theme], then its resolver over [values]. */
fun plateTheme(spec: PlateSpec<*>, theme: PlateTheme?, values: List<String?>): PlateTheme {
    var base = theme ?: PlateTheme.standard()
    spec.borderWidthRatioOverride?.let { base = base.copy(borderWidthRatio = it) }
    spec.inkOverride?.let { base = base.copy(ink = it, plateBorder = it, dividerColor = it, activeColor = it) }
    @Suppress("UNCHECKED_CAST")
    val resolve = spec.resolveTheme as PlateThemeResolver<PlateTheme>?
    return resolve?.invoke(base) { spec.valueOfGroup(it, values) } ?: base
}

/** Every part settled, as the vectors render. */
fun settledFrames(style: PlateAnimationStyle = PlateAnimationStyle()): Frames =
    { PlatePartFrame(PlatePartPhase.settled, 1.0, style.motionFor(it)) }

/** Flutter's Stack clips its children to itself only when one of them overflows it. */
private fun clipOverflow(c: DisplayList, w: Double, h: Double, boxes: List<PlateBox>) {
    if (boxes.any { it.left < 0 || it.top < 0 || it.right > w || it.bottom > h }) c.clipRect(Rect(0.0, 0.0, w, h))
}

private fun glyphStyle(fontSize: Double, color: Int, letterSpacing: Double = 0.0) =
    TextStyle(fontSize, 1.0, color, "Roboto", 700, letterSpacing)

/**
 * [D1] The layers a plate paints in, bottom to top: Flutter's `_MorphingFrame`, `_PlateContent` and `_PlateInputs`.
 *
 * They change at different rates, which is the point of keeping them apart. The [frame] (face, regions, border)
 * changes on a livery fade, a resize or a completion flip; the [artwork] (country panel, flag, bands, rules, labels,
 * decals and their images) only when the spec, the theme or a resolved label's wording does; the [inputs] (mirrors,
 * slots, the restriction banner) on every keystroke. A host repaints only the layers whose display list changed.
 */
enum class PlateLayer { frame, artwork, inputs }

/** One frame of a plate as its three display lists, in view units. */
class PlateLayers(val frame: List<DisplayOp>, val artwork: List<DisplayOp>, val inputs: List<DisplayOp>) {
    operator fun get(layer: PlateLayer) = when (layer) {
        PlateLayer.frame -> frame
        PlateLayer.artwork -> artwork
        PlateLayer.inputs -> inputs
    }

    /** The layers as one display list, bottom to top: what the vectors record. */
    fun flatten(): List<DisplayOp> = frame + artwork + inputs
}

/** Everything one frame of one plate is painted from, resolved once and shared by the layer painters. */
private class Scene(
    val spec: PlateSpec<*>,
    val values: List<String?>,
    val theme: PlateTheme,
    val country: PlateCountry,
    val frames: Frames,
    val view: Pair<Double, Double>,
) {
    val w = spec.canvasWidth
    val h = spec.canvasHeight
    val rim = rimClip(frameGeometry(theme, w, h, frames))

    fun shown(id: PlatePartId) = !frames(id).hidden

    /** [D1] PlatePartAnimator's transition chain around one part's [paint], over its [box]; settled paints it bare. */
    fun animated(c: DisplayList, id: PlatePartId, box: Rect, paint: () -> Unit) {
        val f = frames(id)
        if (f.phase == PlatePartPhase.settled) return paint()
        val look = platePartLook(f)
        if (look.alpha <= 0) return
        if (look.alpha < 1) c.layer(null, look.alpha) else c.save()
        if (look.clip) c.clipRect(plateRevealRect(box, f.motion.origin, f))
        c.translate(look.slideX * box.width, look.slideY * box.height)
        if (look.scale != 1.0) {
            val ox = box.left + box.width * (1 + look.scaleOrigin.x) / 2
            val oy = box.top + box.height * (1 + look.scaleOrigin.y) / 2
            c.translate(ox, oy)
            c.scale(look.scale)
            c.translate(-ox, -oy)
        }
        paint()
        c.restore()
    }

    /** Records [paint] in spec units, contain-fitted to the view and held inside the rim, as its own display list. */
    fun fitted(boxes: List<PlateBox>, paint: (DisplayList) -> Unit): List<DisplayOp> {
        val c = DisplayList()
        val (vw, vh) = view
        val k = min(vw / w, vh / h)
        c.save()
        c.translate((vw - w * k) / 2, (vh - h * k) / 2)
        c.scale(k)
        c.clipRRect(rim)
        clipOverflow(c, w, h, boxes)
        paint(c)
        c.restore()
        return c.ops
    }
}

/** Face, regions, dividers and border, laid out at [frameSize] and stretched to the view. */
private fun Scene.frameLayer(isCompleted: Boolean, frameSize: Pair<Double, Double>?): List<DisplayOp> {
    val c = DisplayList()
    val (vw, vh) = view
    val (fw, fh) = frameSize ?: view
    c.save()
    c.scale(vw / fw, vh / fh)
    paintFrame(c, theme, fw, fh, spec.background, country.panelColor, isCompleted, frames)
    c.restore()
    return c.ops
}

/** The printed furniture: country panel, bands, rules, labels and decals. */
private fun Scene.artworkLayer(labelText: ((Int, String) -> Pair<String, List<Double>?>)?): List<DisplayOp> {
    val t = theme
    val group = { k: String -> spec.valueOfGroup(k, values) }
    val boxes = listOfNotNull(spec.panel?.box) + spec.bands.map { it.box } + spec.rules.map { it.box } + spec.labels.map { it.box } + spec.decals.map { it.box }
    return fitted(boxes) { c ->
        val panel = spec.panel
        if (panel != null && shown(PlatePartId.panel)) {
            animated(c, PlatePartId.panel, panel.box.rect) {
                paintPanel(c, panel, country, t.ink, !spec.background.paintsPanel, shown(PlatePartId.flag), shown(PlatePartId.caption))
            }
        }
        for ((i, b) in spec.bands.withIndex()) {
            if (!shown(PlatePartId.band(i))) continue
            val top = b.topCornerRadius
            val bottom = b.bottomCornerRadius
            animated(c, PlatePartId.band(i), b.box.rect) {
                if (top == 0.0 && bottom == 0.0) c.rect(b.box.rect, Paint(b.color))
                else c.rrect(RRect(b.box.rect, listOf(top, top, top, top, bottom, bottom, bottom, bottom)), Paint(b.color))
            }
        }
        for ((i, r) in spec.rules.withIndex()) {
            c.save()
            c.translate(r.box.left, r.box.top)
            paintDivider(c, Rect(0.0, 0.0, r.box.width, r.box.height), t.dividerColor, frames(PlatePartId.rule(i)))
            c.restore()
        }
        for ((i, l) in spec.labels.withIndex()) {
            if (!shown(PlatePartId.label(i))) continue
            var text = l.resolve?.invoke(group) ?: l.text
            var alphas: List<Double>? = null
            if (l.resolve != null && labelText != null) labelText(i, text).let { text = it.first; alphas = it.second }
            val family = if (l.fontPackage != null) "packages/${l.fontPackage}/${l.fontFamily}" else l.fontFamily ?: "Roboto"
            val g = t.glyphStyle(l.glyphHeight, l.color ?: t.ink)
            val style = TextStyle(g.fontSize, l.lineHeight ?: 1.0, g.color, family, g.fontWeight, 0.0)
            animated(c, PlatePartId.label(i), l.box.rect) { paintTextLine(c, text, l.box.rect, style, spec.textDirection, l.rotated, TextAlign.center, alphas) }
        }
        for ((i, d) in spec.decals.withIndex()) {
            if (!shown(PlatePartId.decal(i))) continue
            val drawing = d.drawing
            val image = d.image
            animated(c, PlatePartId.decal(i), d.box.rect) {
                if (drawing != null) {
                    c.save()
                    c.translate(d.box.left, d.box.top)
                    paintDrawing(c, drawing, d.box.width, d.box.height, DrawingFit.contain)
                    c.restore()
                } else if (image != null) {
                    c.asset(if (image is RasterPlateAsset) "raster" else "svg", image.`package`, image.path, d.box.rect)
                }
            }
        }
    }
}

/** What the user types: mirrors, slots (glyphs, or a field's placeholder and underline) and the restriction banner. */
private fun Scene.inputsLayer(
    mode: PlateMode,
    inputSource: PlateInputSource?,
    rejection: PlateRestriction?,
    hintAt: ((Int) -> String?)?,
    activeIndex: Int?,
    glyphs: ((String, List<String>) -> List<Glyph>)?,
): List<DisplayOp> = fitted(spec.mirrors.map { it.box } + spec.slots.map { it.box }) { c ->
    val t = theme
    for ((i, m) in spec.mirrors.withIndex()) {
        val v = values.getOrNull(m.source)
        if (!shown(PlatePartId.mirror(i)) || v.isNullOrEmpty()) continue
        val alphabet = m.alphabet ?: spec.slots[m.source].alphabet
        val g = t.glyphStyle(m.glyphHeight, t.ink)
        val run = glyphs?.let { f -> { u: List<String> -> f("mirror:$i", u) } }
        animated(c, PlatePartId.mirror(i), m.box.rect) {
            paintGlyphRun(c, alphabet.renderAll(v), m.box.rect, glyphStyle(g.fontSize, g.color), alphabet.direction, glyphs = run)
        }
    }
    for ((i, s) in spec.slots.withIndex()) {
        if (!shown(PlatePartId.slot(i))) continue
        // [D2] Anything but a glyph is a native input the UI layer places at the slot box; its glyphs,
        // placeholder and underline are still painted here, under the transparent field.
        val field = mode == PlateMode.input && inputSource != null && resolveSlotBehavior(mode, s.alphabet.input, inputSource) != SlotBehavior.glyph
        val v = values.getOrNull(i)
        val g = t.glyphStyle(s.box.height, s.color ?: t.ink, s.spacing)
        val style = glyphStyle(g.fontSize, g.color, g.letterSpacing)
        val text = if (v.isNullOrEmpty()) "" else s.render(v)
        val run = glyphs?.let { f -> { u: List<String> -> f("slot:$i", u) } }
        val r = s.box.rect
        animated(c, PlatePartId.slot(i), r) {
            if (!field) paintGlyphRun(c, text, r, style, s.alphabet.direction, glyphs = run)
            else {
                val inset = s.box.height * 0.14
                val hint = hintAt?.invoke(i) ?: s.alphabet.placeholder
                paintGlyphRun(c, text, Rect.fromLTRB(r.left, r.top + inset, r.right, r.bottom - inset), style, s.alphabet.direction, hint to t.inactiveColor, glyphs = run)
                c.rect(Rect.fromLTWH(r.left, r.bottom - 1, r.width, 1.0), Paint(if (!v.isNullOrEmpty() || activeIndex == i) t.activeColor else t.inactiveColor))
            }
        }
    }
    if (rejection != null) {
        val bh = h * 0.42
        val top = (h - bh) / 2
        c.rect(Rect.fromLTWH(0.0, top, w, bh), Paint(t.alertColor))
        val style = TextStyle(h * 0.26, 1.0, 0xFFFFFFFF.toInt(), "Roboto", 800, 0.25)
        paintTextLine(c, rejection.reason, Rect.fromLTWH(h * 0.1, top, w - h * 0.2, bh), style, TextDirection.ltr, false, TextAlign.start)
    }
}

/**
 * [D1] PlateCanvas as its three layers (see [PlateLayer]), in view units.
 *
 * [country] replaces the spec's chrome; [size] is the view's size, the box the plate is drawn
 * into (the canvas by default). The frame is laid out at [frameSize] and stretched to it (by
 * default [size] itself, so a plate resizing between specs draws its face at the size it has
 * now; a leaving ghost passes its own canvas); the artwork and the inputs contain-fit.
 */
fun renderLayers(
    spec: PlateSpec<*>,
    values: List<String?>,
    theme: PlateTheme? = null,
    country: PlateCountry = spec.country,
    frames: Frames = settledFrames(),
    mode: PlateMode = PlateMode.display,
    inputSource: PlateInputSource? = null,
    isCompleted: Boolean = spec.slots.withIndex().all { (i, s) -> s.isComplete(values.getOrNull(i)) },
    rejection: PlateRestriction? = null,
    size: Pair<Double, Double>? = null,
    frameSize: Pair<Double, Double>? = null,
    hintAt: ((Int) -> String?)? = null,
    activeIndex: Int? = null,
    /** A livery tween in flight; the plate paints with it instead of resolving its own theme. */
    resolvedTheme: PlateTheme? = null,
    /** A resolved label's wording on show and, mid-stagger, its per-character alphas. */
    labelText: ((Int, String) -> Pair<String, List<Double>?>)? = null,
    /** A run's units as they animate in and out, by run (`slot:i`, `mirror:i`); absent, they show settled. */
    glyphs: ((String, List<String>) -> List<Glyph>)? = null,
): PlateLayers {
    val scene = Scene(spec, values, resolvedTheme ?: plateTheme(spec, theme, values), country, frames, size ?: (spec.canvasWidth to spec.canvasHeight))
    return PlateLayers(
        scene.frameLayer(isCompleted, frameSize),
        scene.artworkLayer(labelText),
        scene.inputsLayer(mode, inputSource, rejection, hintAt, activeIndex, glyphs),
    )
}

/** [D1] PlateCanvas as one display list: its layers bottom to top (see [renderLayers]), the shape of ports/vectors/render. */
fun renderPlate(
    spec: PlateSpec<*>,
    values: List<String?>,
    theme: PlateTheme? = null,
    country: PlateCountry = spec.country,
    frames: Frames = settledFrames(),
    mode: PlateMode = PlateMode.display,
    inputSource: PlateInputSource? = null,
    isCompleted: Boolean = spec.slots.withIndex().all { (i, s) -> s.isComplete(values.getOrNull(i)) },
    rejection: PlateRestriction? = null,
    size: Pair<Double, Double>? = null,
    frameSize: Pair<Double, Double>? = null,
    hintAt: ((Int) -> String?)? = null,
    activeIndex: Int? = null,
    resolvedTheme: PlateTheme? = null,
    labelText: ((Int, String) -> Pair<String, List<Double>?>)? = null,
): List<DisplayOp> = renderLayers(
    spec, values, theme, country, frames, mode, inputSource, isCompleted, rejection, size, frameSize, hintAt, activeIndex, resolvedTheme, labelText,
).flatten()
